function validGym(s){if(!s||s.version!==1||s.status!=='active'||!['warmup','lift','rest','cooldown'].includes(s.phase)||!['lb','kg'].includes(s.unit)||typeof s.paused!=='boolean'||!Number.isFinite(s.elapsed)||s.elapsed<0||!Number.isFinite(s.remaining)||s.remaining<0||!Array.isArray(s.records))return false;const w=gymWorkouts.find(w=>w.id===s.workoutId);if(!w||!Number.isInteger(s.exercise)||s.exercise<0||s.exercise>=w.exercises.length||!Number.isInteger(s.set)||s.set<1||s.set>w.exercises[s.exercise].sets)return false;const prefix=w.exercises.slice(0,s.exercise).reduce((n,e)=>n+e.sets,0)+s.set-1;const expected=s.phase==='warmup'?0:s.phase==='cooldown'?w.exercises.reduce((n,e)=>n+e.sets,0):prefix+(s.phase==='rest'?1:0);if(s.records.length!==expected)return false;const slots=w.exercises.flatMap(e=>Array.from({length:e.sets},(_,i)=>({exercise:e.id,set:i+1})));return s.records.every((r,i)=>r.exercise===slots[i]?.exercise&&r.set===slots[i]?.set&&w.exercises.some(e=>e.id===r.exercise)&&['lb','kg'].includes(r.unit)&&((r.completed===true&&r.reps===null&&r.weight===null&&r.rir===null)||(Number.isInteger(r.reps)&&r.reps>=0&&r.reps<=100&&Number.isFinite(r.weight)&&r.weight>=0&&r.weight<=2000&&Number.isInteger(r.rir)&&r.rir>=0&&r.rir<=5)));}
